import { EntityTfError } from "../../engine/entity.js";
import { appScopedResourceLabel, expr, tsLabelToTfLabel } from "../../engine/tf/index.js";
import { APP_RESOURCE_TYPE } from "../app/module.js";
import { fieldRefToTfValue } from "../field/to-tf.js";
import { APPROVAL_PROCESS_RESOURCE_TYPE } from "./module.js";
export function approvalChainToTf(entity, ctx) {
    if (entity.kind !== "approvalChain")
        throw new EntityTfError(`approvalChainToTf expects approvalChain; got ${entity.kind}`);
    const payload = entity.payload;
    if (payload === null)
        throw new EntityTfError(`approval chain ${entity.refName} has no payload`);
    const label = appScopedResourceLabel(ctx.appTfLabel, tsLabelToTfLabel(entity.refName));
    const attrs = {
        app_id: expr.resourceAttr(APP_RESOURCE_TYPE, ctx.appTfLabel, ["id"]),
        name: payload.name ?? "",
        number_of_dynamic_approvers: payload.numberOfDynamicApprovers ?? 0,
        managed_by_automation: payload.managedByAutomation ?? false,
        deny_button_text: payload.denyButton ?? "Deny",
        approve_button_text: payload.approveButton ?? "Approve",
    };
    if (payload.stage !== undefined)
        attrs["stage_id"] = expr.local(`${ctx.appTfLabel}_stage_ids_by_key`, [{ index: tsLabelToTfLabel(payload.stage) }]);
    else if (payload.stageId !== undefined)
        attrs["stage_id"] = payload.stageId;
    if (payload.exceptionButton !== undefined)
        attrs["exception_button_text"] = payload.exceptionButton;
    if (payload.defaultReason !== undefined)
        attrs["default_reason"] = payload.defaultReason;
    if (payload.summary !== undefined)
        attrs["approval_summary"] = payload.summary;
    if (payload.lockedFieldIds !== undefined) {
        attrs["locked_field_ids"] = payload.lockedFieldIds.map((field) => {
            if (field.parent !== undefined && field.parent !== "" && field.parent !== ctx.appRefName)
                throw new EntityTfError(`approval chain ${entity.refName}: locked field belongs to ${field.parent}`);
            const value = fieldRefToTfValue(field.fieldType ?? "", field.refName ?? "", ctx.appTfLabel);
            if (value === undefined)
                throw new EntityTfError(`approval chain ${entity.refName}: locked field ${field.refName ?? ""} has no Terraform mapping`);
            return value;
        });
    }
    const block = { kind: "resource", type: APPROVAL_PROCESS_RESOURCE_TYPE, label, attrs };
    return { blocks: [block], address: `${APPROVAL_PROCESS_RESOURCE_TYPE}.${label}` };
}
